mapper.select:
SELECT A.*, B.* FROM ( SELECT tt1.rnum no, tt1.credit_id, tt1.content_id, tt1.person_id, tt1.role, tt1.character, tt1.display_order, tt1.name_ko, tt1.name_org, tt1.profile_image_url, tt1.title_ko, tt1.poster_url, tt1.release_year FROM ( SELECT ROWNUM rnum, t1.* FROM ( SELECT cc.credit_id, cc.content_id, cc.person_id, cc.role, cc."CHARACTER" AS character, cc.display_order, p.name_ko, p.name_org, p.profile_image_url, c.title_ko, c.poster_url, TO_CHAR(c.release_year, 'YYYY-MM-DD') release_year FROM content_credit cc JOIN person p ON cc.person_id = p.person_id JOIN content c ON cc.content_id = c.content_id
ORDER BY cc.content_id ASC, cc.role ASC, cc.display_order ASC, cc.credit_id ASC ) t1 WHERE ROWNUM <= (#{pageSize} * (#{pageNo} - 1) + #{pageSize}) ) tt1 WHERE rnum >= (#{pageSize} * (#{pageNo} - 1) + 1) ) A CROSS JOIN ( SELECT COUNT(*) total_cnt FROM content_credit cc JOIN person p ON cc.person_id = p.person_id JOIN content c ON cc.content_id = c.content_id
) B
